// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue, uniqueSuffix } from '@skyramp/skyramp';
import { createCoupon } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

// Stays local: the shared createCoupon helper always sends an expirationDate key, and these
// cases send a body whose key set omits it.
async function createCouponWithoutExpirationDate(
    client: SkyrampClient,
    headers: Record<string, string>,
    code: string,
    expectedStatus = 400,
    discountPercent: unknown = 10
) {
    // Request Body
    const requestBody: string = `{
        "code": "TESTBOT-VAL-A1",
        "discountPercent": 10
    }`;

    // Execute Request
    const response = await client.sendRequest({
        url: URL_localhost,
        path: "/api/v1/coupons",
        method: "POST",
        body: requestBody,
        headers: headers,
        dataOverride: {"code": code, "discountPercent": discountPercent}
    });

    // Generated Assertions
    expect(response.statusCode, 'status code').toBe(expectedStatus);

    return response;
}

// Stays local: this case's body omits the code key entirely, which no shared helper sends.
async function createCouponWithoutCode(
    client: SkyrampClient,
    headers: Record<string, string>,
    expectedStatus = 400
) {
    // Request Body
    const requestBody: string = `{
        "discountPercent": 10
    }`;

    // Execute Request
    const response = await client.sendRequest({
        url: URL_localhost,
        path: "/api/v1/coupons",
        method: "POST",
        body: requestBody,
        headers: headers
    });

    // Generated Assertions
    expect(response.statusCode, 'status code').toBe(expectedStatus);

    return response;
}

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // The code the accepted first request creates; the duplicate case re-sends this exact value.
    const couponCode = uniqueSuffix("TESTBOT-VAL-A1");

    // Accepted request at the discountPercent upper boundary 100.
    const couponsPostResponse = await createCoupon(client, headers, couponCode, 201, 100, "2027-06-30T12:00:00.000Z");
    expect(couponsPostResponse.statusCode, 'status code').toBe(201);
    expect(getResponseValue(couponsPostResponse, "response.code"), 'code').toBe(couponCode);
    expect(getResponseValue(couponsPostResponse, "response.discountPercent"), 'discountPercent').toBe(100);

    // A code that already exists is refused.
    const couponsPost1Response = await createCouponWithoutExpirationDate(client, headers, couponCode, 409, 10);
    expect(couponsPost1Response.statusCode, 'status code').toBe(409);
    expect(getResponseValue(couponsPost1Response, "response"), 'duplicate code message').toBe("A coupon with this code already exists.");

    // A body with no code is refused.
    const couponsPost2Response = await createCouponWithoutCode(client, headers, 400);
    expect(couponsPost2Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(couponsPost2Response, "response"), 'missing code message').toBe("A valid coupon code is required.");

    // discountPercent one past the upper bound is refused.
    const couponsPost3Response = await createCouponWithoutExpirationDate(client, headers, uniqueSuffix("TESTBOT-VAL-HIGH"), 400, 101);
    expect(couponsPost3Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(couponsPost3Response, "response"), 'discountPercent 101 message').toBe("discountPercent must be a number between 0 and 100.");

    // discountPercent one past the lower bound is refused.
    const couponsPost4Response = await createCouponWithoutExpirationDate(client, headers, uniqueSuffix("TESTBOT-VAL-LOW"), 400, -1);
    expect(couponsPost4Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(couponsPost4Response, "response"), 'discountPercent -1 message').toBe("discountPercent must be a number between 0 and 100.");

    // A non-numeric discountPercent is refused.
    const couponsPost5Response = await createCouponWithoutExpirationDate(client, headers, uniqueSuffix("TESTBOT-VAL-STR"), 400, "10");
    expect(couponsPost5Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(couponsPost5Response, "response"), 'string discountPercent message').toBe("discountPercent must be a number between 0 and 100.");

    // An expirationDate that is not an ISO-8601 date string is refused, and no coupon is created.
    const couponsPost6Response = await createCoupon(client, headers, uniqueSuffix("TESTBOT-VAL-BADDATE"), 400, 50, "not-a-date");
    expect(couponsPost6Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(couponsPost6Response, "response.id"), 'no coupon created for a malformed expirationDate').toBeNull();
    expect(getResponseValue(couponsPost6Response, "response.expirationDate"), 'no expirationDate persisted').toBeNull();

    // A numeric expirationDate is refused — the description specifies an ISO-8601 string — and no coupon is created.
    const couponsPost7Response = await createCoupon(client, headers, uniqueSuffix("TESTBOT-VAL-NUMDATE"), 400, 50, 12345);
    expect(couponsPost7Response.statusCode, 'status code').toBe(400);
    expect(getResponseValue(couponsPost7Response, "response.id"), 'no coupon created for a numeric expirationDate').toBeNull();
    expect(getResponseValue(couponsPost7Response, "response.expirationDate"), 'no expirationDate persisted').toBeNull();
});
